results.js:
const bar = morse.el("div", {
  id: "morse-read-progress",
  style: "position:fixed !important;top:0 !important;left:0 !important;height:4px !important;width:0 !important;background:#222 !important;z-index:2147483647 !important;pointer-events:none !important;"
});
document.body.appendChild(bar);

function updateProgress() {
  const root = document.documentElement;
  const max = root.scrollHeight - root.clientHeight;
  const ratio = max > 0 ? Math.min(1, Math.max(0, root.scrollTop / max)) : 0;
  bar.style.setProperty("width", (ratio * 100) + "%", "important");
}

morse.on(window, "scroll", updateProgress);
morse.every(100, updateProgress);
updateProgress();

