results.js:
morse.watch("body", body => {
  const bar = morse.el("div");
  const wrap = morse.el("div", { id: "morse-progress" }, bar);
  body.appendChild(wrap);
  const update = () => {
    const d = document.documentElement;
    const max = d.scrollHeight - d.clientHeight;
    const pct = max > 0 ? (d.scrollTop || document.body.scrollTop) / max * 100 : 0;
    bar.style.width = Math.min(100, Math.max(0, pct)) + "%";
  };
  morse.on(window, "scroll", update);
  morse.on(window, "resize", update);
  update();
});

const bar = morse.el("div", {
  id: "morse-progress",
  style: "position:fixed;top:0;left:0;height:4px;width:0;background:#222;z-index:99999;pointer-events:none;transition:width .1s linear"
});
document.body.appendChild(bar);

const update = () => {
  const max = document.documentElement.scrollHeight - window.innerHeight;
  const pct = max > 0 ? Math.min(100, (window.scrollY / max) * 100) : 0;
  bar.style.width = pct + "%";
};

morse.on(window, "scroll", update);
morse.on(window, "resize", update);
update();

