morse.on(document, "keydown", e => {
  if (e.key.toLowerCase() !== "c" || e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.target.closest?.("input, textarea, select, [contenteditable]")) return;
  const btn = morse.$$('button[aria-label="Clear canvas"]')[0];
  if (btn) btn.click();
});

morse.on(document, "keydown", e => {
  if (e.key.toLowerCase() !== "c" || e.ctrlKey || e.metaKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  const btn = document.querySelector('button[aria-label="Clear canvas"]');
  if (btn) {
    e.preventDefault();
    btn.click();
  }
});

