morse.watch('[aria-label="Tools"]', tools => {
  if (tools.querySelector('[data-morse-save]')) return;
  const btn = morse.el('button', {
    'aria-label': 'Save as PNG',
    'data-morse-save': '',
    title: 'Save as PNG',
    text: '💾',
    style: 'width:38px;height:38px;margin-top:8px;border:none;border-radius:8px;background:transparent;cursor:pointer;font-size:18px;',
    on: {
      click: () => {
        const board = document.getElementById('board');
        if (!board) return;
        board.toBlob(blob => {
          if (!blob) return;
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'sketch.png';
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        }, 'image/png');
      }
    }
  });
  tools.appendChild(btn);
});

