morse.watch("body > div.mn > div.row2 > div.tbl > h3", h3 => {
  const btn = morse.el("button", {
    class: "morse-csv-btn",
    type: "button",
    text: "Export CSV",
    on: { click: () => {
      const table = h3.parentElement.querySelector("table");
      if (!table) return morse.toast("No orders table found");
      const rows = [...table.querySelectorAll("tr")].map(tr =>
        [...tr.children].map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"').join(",")
      );
      const url = URL.createObjectURL(new Blob([rows.join("\n")], { type: "text/csv" }));
      const a = morse.el("a", { href: url, download: "orders.csv" });
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      morse.toast("Exported " + (rows.length - 1) + " orders");
    } }
  });
  h3.after(btn);
});

