results.js:
morse.watch("th.am", th => {
  let dir = 1;
  morse.on(th, "click", () => {
    dir = -dir;
    const tbody = th.closest("table").querySelector("tbody");
    const num = tr => parseFloat(tr.querySelector("td.am").textContent.replace(/[^\d.-]/g, "")) || 0;
    const rows = Array.from(tbody.querySelectorAll("tr"));
    rows.sort((a, b) => dir * (num(a) - num(b)));
    rows.forEach(r => tbody.appendChild(r));
  });
});

