results.js:
morse.watch("th.am", th => {
  morse.on(th, "click", () => {
    const dir = th.dataset.sort === "asc" ? "desc" : "asc";
    th.dataset.sort = dir;
    const table = th.closest("table");
    const body = table.tBodies[0];
    const idx = th.cellIndex;
    const num = r => parseFloat(r.cells[idx].textContent.replace(/[^0-9.\-]/g, "")) || 0;
    const rows = Array.from(body.rows).sort((a, b) => dir === "asc" ? num(a) - num(b) : num(b) - num(a));
    rows.forEach(r => body.appendChild(r));
  });
});

