results.js:
morse.watch("div.tbl > div.sc > table", el => {
  const sum = [...el.querySelectorAll("tbody td.am")]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  const text = sum.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const old = el.querySelector("tfoot.morse-total");
  if (old && old.querySelector("td.am").textContent === text) return;
  if (old) old.remove();
  el.appendChild(morse.el("tfoot", { class: "morse-total" },
    morse.el("tr", {},
      morse.el("td", { colspan: "4", text: "Total" }),
      morse.el("td", { class: "am", text: text })
    )
  ));
}, { live: true });

morse.watch(".tbl .sc > table", t => {
  let tf = t.querySelector("tfoot");
  if (!tf) {
    tf = morse.el("tfoot", {}, morse.el("tr", {},
      morse.el("td", { colspan: 4, text: "Total" }),
      morse.el("td", { class: "am" })));
    t.appendChild(tf);
  }
  const sum = [...t.querySelectorAll("tbody td.am")].reduce((s, td) => s + (parseFloat(td.textContent.replace(/[^0-9.-]/g, "")) || 0), 0);
  tf.querySelector("td.am").textContent = sum.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}, { live: true });

