results.js:
morse.watch("div.tbl > div.sc > table", (table) => {
  const cells = table.querySelectorAll("tbody td.am");
  if (!cells.length) return;
  const sum = [...cells].reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  const amount = sum.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const old = table.querySelector("tfoot.mtotal");
  if (old && old.dataset.total === amount) return;
  if (old) old.remove();
  table.appendChild(
    morse.el("tfoot", { class: "mtotal", "data-total": amount },
      morse.el("tr", {},
        morse.el("td", { colspan: "4", text: "Total" }),
        morse.el("td", { class: "am", text: amount })
      )
    )
  );
}, { live: true });

