        const ed = document.querySelector('div[role="textbox"]');
        if (!ed) return;
        const d = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
        ed.focus();
        const sel = getSelection();
        if (!sel.rangeCount || !ed.contains(sel.anchorNode)) {
          const r = document.createRange();
          r.selectNodeContents(ed);
          r.collapse(false);
          sel.removeAllRanges();
          sel.addRange(r);
        }
        if (!document.execCommand('insertText', false, d)) {
          ed.append(d);
        }
      }
    }
  });
  bar.append(btn);
});

