      click: () => {
        const d = new Date();
        const today = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const sel = window.getSelection();
        const box = document.querySelector('div[role="textbox"]');
        if (!box) return;
        box.focus();
        if (sel && sel.rangeCount && box.contains(sel.anchorNode)) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(today));
          range.collapse(false);
        } else {
          box.appendChild(morse.el('p', { text: today }));
        }
      }
    }
  });
  bar.appendChild(btn);
});

