let bypass = false;
let dialog = null;

function closeDialog() {
  if (dialog) { dialog.remove(); dialog = null; }
}

function askDelete(btn) {
  closeDialog();
  const cancel = morse.el("button", {
    text: "Cancel",
    style: "padding:6px 12px;border:1px solid rgba(0,0,0,.15);border-radius:6px;background:#fff;color:inherit;font:inherit;cursor:pointer",
    on: { click: closeDialog }
  });
  const ok = morse.el("button", {
    text: "Delete",
    style: "padding:6px 12px;border:0;border-radius:6px;background:#dc2626;color:#fff;font:inherit;cursor:pointer",
    on: { click: () => {
      closeDialog();
      bypass = true;
      try { btn.click(); } finally { bypass = false; }
    } }
  });
  dialog = morse.el("div", {
    style: "position:fixed;inset:0;background:rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;z-index:9999;font:inherit",
    on: { click: e => { if (e.target === dialog) closeDialog(); } }
  }, morse.el("div", {
    role: "alertdialog",
    "aria-label": "Confirm delete",
    style: "background:#fff;color:inherit;border-radius:10px;padding:16px 18px;box-shadow:0 10px 30px rgba(0,0,0,.2);display:flex;flex-direction:column;gap:12px;min-width:240px"
  },
    morse.el("div", { text: "Delete this task?", style: "font-weight:600" }),
    morse.el("div", { style: "display:flex;gap:8px;justify-content:flex-end" }, cancel, ok)
  ));
  document.body.appendChild(dialog);
