morse.el("button", {
  text: "Sort: price low to high",
  style: "margin-left:auto;padding:6px 12px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:13px;cursor:pointer"
}, "")

morse.watch('#__next > div:nth-of-type(2) > main > div:nth-of-type(1)', bar => {
  const cardsSel = '#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div';
  const price = c => {
    const t = c.children[1]?.children[2]?.textContent || c.textContent;
    const m = t.match(/\$\s*([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, '')) : Infinity;
  };
  const btn = morse.el('button', {
    text: 'Sort: price low → high',
    style: 'margin-left:auto;padding:6px 12px;font:inherit;font-size:13px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;cursor:pointer;',
    on: { click: () => {
      const cards = morse.$$(cardsSel);
      const on = btn.dataset.on !== '1';
      btn.dataset.on = on ? '1' : '0';
      if (on) {
        [...cards].map((c, i) => ({ c, i, p: price(c) }))
          .sort((a, b) => a.p - b.p || a.i - b.i)
          .forEach((x, idx) => { x.c.style.order = idx; });
      } else {
        cards.forEach(c => { c.style.order = ''; });
      }
      btn.style.background = on ? 'rgb(28,25,23)' : 'transparent';
      btn.style.color = on ? 'rgb(250,250,249)' : 'inherit';
      btn.textContent = on ? 'Sorted: lowest first ✓' : 'Sort: price low → high';
    } }
  });
  bar.appendChild(btn);
});

morse.watch('#__next > div:nth-of-type(2) > main > div:nth-of-type(1)', bar => {
  const btn = morse.el('button', {
    id: 'morse-sort-price',
    text: 'Sort by price: low to high',
    style: 'margin-left:auto;padding:6px 12px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;font:inherit;cursor:pointer',
    on: {
      click: () => {
        const grid = document.querySelector('#__next > div:nth-of-type(2) > main > div:nth-of-type(2)');
        if (!grid) return;
        const price = c => {
          const m = c.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
          return m ? parseFloat(m[1].replace(/,/g, '')) : Infinity;
        };
        [...grid.children]
          .sort((a, b) => price(a) - price(b))
          .forEach(c => grid.appendChild(c));
        morse.toast('Sorted by price, lowest first');
      }
    }
  });
  bar.appendChild(btn);
});

