morse.watch('[data-testid="player-controls"]', el => {
  if (el.querySelector('.sleep-timer')) return;
  const picker = morse.el('select', { class: 'sleep-timer', 'aria-label': 'Sleep timer', style: 'background:transparent;color:inherit;font:inherit;border:1px solid currentColor;border-radius:6px;padding:2px 4px;' },
    morse.el('option', { value: '0', text: 'Sleep: off' }),
    morse.el('option', { value: '5', text: '5 min' }),
    morse.el('option', { value: '15', text: '15 min' }),
    morse.el('option', { value: '30', text: '30 min' }),
    morse.el('option', { value: '60', text: '1 hour' })
  );
  let timer = null;
  morse.on(picker, 'change', () => {
    clearTimeout(timer);
    const mins = Number(picker.value);
    if (!mins) { morse.toast('Sleep timer off'); return; }
    timer = setTimeout(() => {
      const pause = document.querySelector('button[data-testid="play-pause"]');
      if (pause && pause.getAttribute('aria-label') === 'Pause') pause.click();
      morse.toast('Sleep timer: playback paused');
      picker.value = '0';
    }, mins * 60 * 1000);
    morse.toast(`Sleep timer set for ${mins} min`);
  });
  el.appendChild(picker);
});

const opts = [0, 5, 15, 30, 60];
let i = 0, end = 0;
const fmt = ms => {
  const s = Math.ceil(ms / 1000);
  return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
};
const render = () => {
  morse.$$('button[aria-label="Sleep timer"]').forEach(b => {
    b.classList.toggle("on", !!end);
    b.textContent = end ? "☾ " + fmt(Math.max(0, end - Date.now())) : "☾";
    b.title = end ? "Sleep timer: stops in " + fmt(Math.max(0, end - Date.now())) : "Sleep timer (off)";
  });
};
morse.watch('[data-testid="player-controls"] .btns', el => {
  el.appendChild(morse.el("button", {
    "aria-label": "Sleep timer",
    text: "☾",
    on: { click: () => {
      i = (i + 1) % opts.length;
      end = opts[i] ? Date.now() + opts[i] * 60000 : 0;
      morse.toast(opts[i] ? "Sleep timer: " + opts[i] + " min" : "Sleep timer off");
      render();
    } }
  }));
  render();
});
morse.every(1000, () => {
  if (end && Date.now() >= end) {
    end = 0; i = 0;
    const pp = document.querySelector('[data-testid="play-pause"]');
    if (pp && pp.getAttribute("aria-label") === "Pause") pp.click();
    morse.toast("Sleep timer ended");
  }
  render();
});

morse.watch('[data-testid="player-controls"] .btns', (row) => {
  const steps = [0, 15, 30, 45, 60];
  let i = 0;
  let endAt = 0;
  const btn = morse.el('button', {
    'data-testid': 'sleep-timer',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer',
    text: 'Zzz',
    on: { click: () => {
      i = (i + 1) % steps.length;
      endAt = i ? Date.now() + steps[i] * 60000 : 0;
      btn.textContent = i ? steps[i] + 'm' : 'Zzz';
      morse.toast(i ? 'Sleep in ' + steps[i] + ' min' : 'Sleep timer off');
    } }
  });
  row.appendChild(btn);
  morse.every(1000, () => {
    if (endAt && Date.now() >= endAt) {
      endAt = 0;
      i = 0;
      btn.textContent = 'Zzz';
      const pp = document.querySelector('[data-testid="play-pause"]');
      if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
      morse.toast('Sleep timer: playback paused');
    }
  });
});

