results.js:
morse.watch("#where", h => {
  const b = morse.el("button", {
    id: "all-off",
    type: "button",
    text: "⏻ Turn all devices off",
    on: {
      click: () => {
        let n = 0;
        morse.$$("device-card >>> button").forEach(btn => {
          const l = btn.getAttribute("aria-label") || "";
          if (!btn.disabled && /:\s*on$/.test(l)) { btn.click(); n++; }
        });
        morse.toast(n ? `Turned off ${n} device${n > 1 ? "s" : ""}` : "All devices already off");
      }
    }
  });
  h.insertAdjacentElement("afterend", b);
  return () => b.remove();
});

